import {GUIDES} from './elder-guide.js';
const $=id=>document.getElementById(id),backend=()=>window.CAGE_BACKEND;
let blocked=false,user='',tour=null;
const profile=()=>blocked?null:backend()?.currentProfile?.();
const allowed=view=>{const p=profile();return !!p&&p.active!==false&&p.role!=='shared'&&(view==='mywork'||['edit','view'].includes(backend()?.moduleLevel?.(view)));};
const current=()=>typeof activeView==='string'?activeView:'mywork';
const label=view=>document.querySelector(`.nav-item[data-view="${view}"]>span:nth-child(2)`)?.textContent||view;
const visible=el=>el&&!el.hidden&&el.getClientRects().length&&getComputedStyle(el).visibility!=='hidden';
const launcher=document.createElement('button');launcher.id='elder-launcher';launcher.textContent='Elder · Help';launcher.hidden=true;launcher.setAttribute('aria-controls','elder-panel');launcher.setAttribute('aria-expanded','false');document.body.append(launcher);
const panel=document.createElement('aside');panel.id='elder-panel';panel.hidden=true;panel.setAttribute('aria-label','Elder help');panel.innerHTML=`<header><div><span class="elder-mark" aria-hidden="true">E</span><div><h2>Elder</h2><p>Your guide to CAGE</p></div></div><button id="elder-close" aria-label="Close Elder">×</button></header><p class="elder-intro">Find your way, one step at a time. Built-in help, with no AI connection.</p><button id="elder-around">Show me around</button><label for="elder-search">What would you like to do?</label><input id="elder-search" type="search" placeholder="Search: invoice, task, upload…"><p id="elder-status" role="status"></p><div id="elder-results"></div><div id="elder-detail" hidden></div>`;document.body.append(panel);
function close(){panel.hidden=true;launcher.setAttribute('aria-expanded','false');}
function list(){const terms=$('elder-search').value.toLowerCase().match(/[a-z]{3,}/g)||[];const ignored=new Set(['how','can','the','and','with','for','want']);const words=terms.filter(t=>!ignored.has(t));const matches=GUIDES.filter(g=>allowed(g.view)).map(g=>({g,score:words.reduce((n,t)=>n+((g.title+' '+g.keywords).toLowerCase().includes(t)?1:0),0)})).filter(x=>!words.length||x.score).sort((a,b)=>b.score-a.score||Number(b.g.view===current())-Number(a.g.view===current()));const box=$('elder-results');box.replaceChildren();$('elder-detail').hidden=true;$('elder-status').textContent=matches.length?'Choose a guide or start a walkthrough.':'No matching guide. Try “invoice”, “project”, “task” or “chat”.';for(const {g}of matches){const b=document.createElement('button');b.className='elder-guide';b.textContent=g.title;b.onclick=()=>show(g);box.append(b);}}
function show(g){if(!allowed(g.view))return;const box=$('elder-detail');box.replaceChildren();box.hidden=false;const h=document.createElement('h3');h.textContent=g.title;const ol=document.createElement('ol');for(const s of g.steps){const li=document.createElement('li');li.textContent=s;ol.append(li);}const b=document.createElement('button');b.textContent='Walk me through';b.className='elder-primary';b.onclick=()=>walk(g);box.append(h,ol,b);box.scrollIntoView({block:'nearest'});}
const targets={quotes:['[data-finance-section="quotes"]','#new-quote-button'],invoices:['[data-finance-section="invoices"]','#new-invoice-button'],personal:['#new-standalone-task','#my-standalone-tasks'],projects:['#new-project-button'],files:['[data-open-project]'],requests:['#new-request-button'],crm:['#new-deal-button'],chat:['#new-direct-chat','#new-group-chat','#chat-input'],calendar:['#new-event-button'],training:['#new-training-program-button'],tenders:['[data-opp-refresh]','[data-opp-sources]'],tasks:['#add-task-top']};
function start(steps){if(!window.driver?.js?.driver){$('elder-status').textContent='The walkthrough could not load. You can still read the guide.';return;}close();tour=window.driver.js.driver({showProgress:true,allowClose:true,disableActiveInteraction:true,nextBtnText:'Next',prevBtnText:'Back',doneBtnText:'Done',steps,onDestroyed:()=>{tour=null;launcher.focus();}});tour.drive();}
async function walk(g){if(!allowed(g.view))return;if(document.querySelector('dialog[open]')){$('elder-status').textContent='Finish or close the open form first. Your draft will not be changed.';return;}setView(g.view);await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));if(!allowed(g.view))return;const steps=[];const nav=document.querySelector(`.nav-item[data-view="${g.view}"]`);if(visible(nav))steps.push({element:nav,popover:{title:label(g.view),description:'This is where you find this workflow.'}});for(const sel of targets[g.id]||[]){const el=[...document.querySelectorAll(sel)].find(e=>visible(e)&&!e.disabled);if(el)steps.push({element:el,popover:{title:g.title,description:'After this walkthrough, use this control to continue. Elder does not click, save or send for you.'}});}steps.push({popover:{title:g.title,description:g.steps.map((s,i)=>`${i+1}. ${s}`).join('<br><br>')}});start(steps);}
$('elder-around').onclick=()=>{if(document.querySelector('dialog[open]')){$('elder-status').textContent='Finish or close the open form before starting a tour.';return;}const steps=GUIDES.filter(g=>allowed(g.view)).filter((g,i,a)=>a.findIndex(x=>x.view===g.view)===i).map(g=>({g,el:document.querySelector(`.nav-item[data-view="${g.view}"]`)})).filter(x=>visible(x.el)).map(({g,el})=>({element:el,popover:{title:label(g.view),description:g.steps[0]}}));if(!steps.length)steps.push({popover:{title:'Welcome to CAGE',description:'Open Elder and search for a workflow. On smaller screens, open the navigation menu to explore modules.'}});start(steps);};
launcher.onclick=()=>{panel.hidden=!panel.hidden;launcher.setAttribute('aria-expanded',String(!panel.hidden));if(!panel.hidden){list();$('elder-search').focus();}};$('elder-close').onclick=()=>{close();launcher.focus();};$('elder-search').oninput=list;
function sync(){const p=profile();const id=p&&p.active!==false&&p.role!=='shared'?p.id:'';launcher.hidden=!id;if(id!==user){user=id;close();tour?.destroy();$('elder-search').value='';$('elder-detail').replaceChildren();$('elder-results').replaceChildren();}if(!id)tour?.destroy();}
function logout(){blocked=true;sync();}
window.addEventListener('cage:session-ready',()=>{blocked=false;sync();if(!panel.hidden)list();});window.addEventListener('cage:access-closed',logout);$('sign-out-button')?.addEventListener('click',logout,true);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!panel.hidden){close();launcher.focus();}});setInterval(sync,1000);sync();
// Discard obsolete local AI conversation copies. Elder never sends questions or records anywhere.
try{Object.keys(sessionStorage).filter(k=>k.startsWith('cage-einstein:')).forEach(k=>sessionStorage.removeItem(k));}catch{}
